<template><view class="p"><jk-page-nav title="提现记录"/><view v-for="x in list" :key="x.id" class="card" @click="go(x.id)"><b>¥ {{x.amount}}</b><text>{{x.withdrawStatusText || x.statusText || withdrawStatusText(x.status)}}</text><text>申请人：{{x.applicantName || '用户不存在'}}<text v-if="x.applicantPhone"> / {{x.applicantPhone}}</text></text><text v-if="x.roleName">身份：{{x.roleName}}</text><text>{{x.createTime}}</text></view></view></template><script>import JkPageNav from '@/components/jk/jk-page-nav.vue';import{getJkWithdrawList}from'@/api/jk.js';import{jkWithdrawStatusText}from'@/utils/jk-display.js';export default{components:{JkPageNav},data(){return{list:[]}},onShow(){getJkWithdrawList().then(r=>this.list=r.data||r||[])},methods:{withdrawStatusText(status){return jkWithdrawStatusText(status)},go(id){uni.navigateTo({url:'/pages/jk/withdraw/detail?id='+id})}}}</script><style scoped>.p{min-height:100vh;background:#f3fbf8;padding:24rpx}.card{background:#fff;border-radius:18rpx;margin-bottom:16rpx;padding:24rpx;display:flex;flex-direction:column;gap:8rpx}.card b{font-size:36rpx;color:#16856b}.card text{font-size:24rpx;color:#78918b}</style>
